import { DEFAULT_PARTITION } from '@sanity/workflow-engine';
import { fail, isAuthRejection } from './fail.js';
import { canPromptOnStderr, confirmOnStderr } from './prompt.js';
import { resourceLabel } from './ui.js';
export function defaultPartitionWarning(deployment, deployedPartitions) {
    if (deployment.partition !== DEFAULT_PARTITION ||
        deployedPartitions.length === 0 ||
        deployedPartitions.includes(DEFAULT_PARTITION)) {
        return undefined;
    }
    const [only] = deployedPartitions;
    const existing = deployedPartitions.length === 1
        ? `This resource's definitions are in partition "${only}". To deploy alongside them instead, set partition: "${only}" on this deployment.`
        : `This resource's definitions are in partitions ${deployedPartitions.join(', ')}. To deploy alongside one of those instead, set partition on this deployment.`;
    return [
        `Partition "${DEFAULT_PARTITION}" of ${resourceLabel(deployment.workflowResource)} has no workflow definitions yet, so deployment "${deployment.name}" will be the first there.`,
        existing,
    ].join('\n');
}
export async function confirmDefaultPartitions({ deployments, deployedPartitions, dryRun, warn, }) {
    const warnings = await Promise.all(deployments
        .filter((deployment) => deployment.partition === DEFAULT_PARTITION)
        .map((deployment) => lookUpWarning(deployment, deployedPartitions)));
    const found = warnings.filter((warning) => warning !== undefined);
    if (found.length === 0) {
        return;
    }
    for (const warning of found) {
        warn(warning);
    }
    if (dryRun || !canPromptOnStderr()) {
        return;
    }
    if (!(await confirmOnStderr(`Deploy to partition "${DEFAULT_PARTITION}"?`, true))) {
        fail('Cancelled — nothing was deployed.');
    }
}
async function lookUpWarning(deployment, deployedPartitions) {
    try {
        return defaultPartitionWarning(deployment, await deployedPartitions(deployment));
    }
    catch (error) {
        if (isAuthRejection(error)) {
            throw error;
        }
        return undefined;
    }
}
